	private static void assertSeededSettings(
		FakeStore store,
		Map<String, Object> settings,
		String overriddenKey)
	{
		for (Map.Entry<String, Object> setting : settings.entrySet())
		{
			if (!overriddenKey.equals(setting.getKey()))
			{
				Assert.assertEquals(
					setting.getValue(),
					store.value(InteractionCueConfig.GROUP, setting.getKey())
				);
			}
		}
	}

	private static final class FakeStore implements InteractionCueConfigMigration.Store
	{
		private final Map<String, Object> values = new LinkedHashMap<>();
		private final List<String> writes = new ArrayList<>();

		@Override
		public String get(String group, String key)
		{
			Object value = value(group, key);
			if (value == null)
			{
				return null;
			}
			if (value instanceof Enum)
			{
				return ((Enum<?>) value).name();
			}
			return String.valueOf(value);
		}

		@Override
		public Iterable<String> keys(String prefix)
		{
			return values.keySet().stream()
				.filter(key -> key.startsWith(prefix))
				.collect(Collectors.toList());
		}

		@Override
		public void set(String group, String key, Object value)
		{
			values.put(group + "." + key, value);
			writes.add(key);
		}

		private void put(String group, String key, Object value)
		{
			values.put(group + "." + key, value);
		}

		private Object value(String group, String key)
		{
			return values.get(group + "." + key);
		}
	}
}

package com.interactioncue;

import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;
import org.junit.Assert;
import org.junit.Test;

public class InteractionCueInventorySnapshotTest
{
	@Test
	public void ignoresUnusedTrailingSlots()
	{
		InteractionCueInventorySnapshot compact = snapshot(item(ItemID.RANARR_WEED, 1));
		InteractionCueInventorySnapshot padded = snapshot(
			item(ItemID.RANARR_WEED, 1),
			null,
			null
		);

		Assert.assertTrue(compact.matches(padded));
	}

	@Test
	public void keepsSlotAndQuantityChangesDistinct()
	{
		InteractionCueInventorySnapshot original = snapshot(
			item(ItemID.RANARR_WEED, 1),
			item(ItemID.RANARRVIAL, 2)
		);

		Assert.assertFalse(original.matches(snapshot(
			item(ItemID.RANARRVIAL, 2),
			item(ItemID.RANARR_WEED, 1)
		)));
		Assert.assertFalse(original.matches(snapshot(
			item(ItemID.RANARR_WEED, 1),
			item(ItemID.RANARRVIAL, 1)
		)));
	}

	@Test
	public void totalsDuplicateStacksByItemId()
	{
		InteractionCueInventorySnapshot inventory = snapshot(
			item(ItemID.RANARR_WEED, 3),
			item(ItemID.RANARRVIAL, 1),
			item(ItemID.RANARR_WEED, 7)
		);

		Assert.assertEquals(10L, inventory.getTotalQuantity(ItemID.RANARR_WEED));
		Assert.assertEquals(1L, inventory.getTotalQuantity(ItemID.RANARRVIAL));
		Assert.assertEquals(0L, inventory.getTotalQuantity(ItemID.COINS));
	}

	@Test
	public void findsFirstMatchingSlotInInventoryOrder()
	{
		InteractionCueInventorySnapshot inventory = snapshot(
			item(ItemID.RANARR_WEED, 1),
			null,
			item(ItemID.RANARRVIAL, 1),
			item(ItemID.COINS, 1),
			item(ItemID.RANARRVIAL, 1)
		);

		Assert.assertEquals(
			2,
			inventory.findFirstSlot(ItemID.RANARRVIAL, -1)
		);
	}

	@Test
	public void excludesReservedSourceSlotFromSearch()
	{
		InteractionCueInventorySnapshot inventory = snapshot(
			item(ItemID.RANARRVIAL, 1),
			null,
			item(ItemID.RANARRVIAL, 1)
		);

		Assert.assertEquals(
			2,
			inventory.findFirstSlot(ItemID.RANARRVIAL, 0)
		);
		Assert.assertEquals(
			-1,
			inventory.findFirstSlot(ItemID.RANARR_WEED, 0)
		);
	}

	@Test
	public void readsMissingSlotsAsEmpty()
	{
		InteractionCueInventorySnapshot inventory = snapshot(
			item(ItemID.RANARR_WEED, 3),
			item(ItemID.RANARRVIAL, 2)
		);

		Assert.assertEquals(ItemID.RANARR_WEED, inventory.getItemIdAt(0));
		Assert.assertEquals(3, inventory.getQuantityAt(0));
		Assert.assertEquals(-1, inventory.getItemIdAt(-1));
		Assert.assertEquals(0, inventory.getQuantityAt(-1));
		Assert.assertEquals(-1, inventory.getItemIdAt(2));
		Assert.assertEquals(0, inventory.getQuantityAt(2));
	}

	private static InteractionCueInventorySnapshot snapshot(Item... items)
	{
		return InteractionCueInventorySnapshot.capture(items);
	}

	private static Item item(int id, int quantity)
	{
		return new Item(id, quantity);
	}
}

package com.interactioncue;

import net.runelite.api.Item;
import net.runelite.api.MenuAction;
import net.runelite.api.gameval.InterfaceID;

final class InteractionCueClickTarget
{
	private InteractionCueClickTarget()
	{
	}

	static boolean isInventoryAction(MenuAction action, int parentId)
	{
		return action == MenuAction.WIDGET_TARGET_ON_WIDGET
			&& parentId == InterfaceID.Inventory.ITEMS;
	}

	static boolean matches(
		int menuSlot,
		int widgetSlot,
		int widgetItemId,
		Item inventoryItem)
	{
		if (menuSlot < 0 || widgetSlot != menuSlot)
		{
			return false;
		}

		if (inventoryItem == null
			|| inventoryItem.getId() <= 0
			|| inventoryItem.getQuantity() <= 0)
		{
			return false;
		}

		return widgetItemId <= 0 || widgetItemId == inventoryItem.getId();
	}
}

package com.interactioncue;

public enum InteractionCueTooltipOrigin
{
	AUTO("Auto"),
	TOP_LEFT("Top left"),
	TOP_CENTER("Top center"),
	TOP_RIGHT("Top right"),
	CENTER_LEFT("Center left"),
	CENTER("Center"),
	CENTER_RIGHT("Center right"),
	BOTTOM_LEFT("Bottom left"),
	BOTTOM_CENTER("Bottom center"),
	BOTTOM_RIGHT("Bottom right");

	private final String name;

	InteractionCueTooltipOrigin(String name)
	{
		this.name = name;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.interactioncue;

final class InteractionCueConfigProfileTracker
{
	private long observedProfileId = Long.MIN_VALUE;
	private boolean switchInProgress;

	synchronized void initialize(long profileId)
	{
		observedProfileId = profileId;
		switchInProgress = false;
	}

	synchronized boolean onConfigChanged(long profileId)
	{
		if (observedProfileId != profileId)
		{
			observedProfileId = profileId;
			switchInProgress = true;
		}
		return switchInProgress;
	}

	synchronized void beginProfileChanged(long profileId)
	{
		observedProfileId = profileId;
		switchInProgress = true;
	}

	synchronized void finishProfileChanged(long profileId)
	{
		if (observedProfileId == profileId)
		{
			switchInProgress = false;
		}
	}
}

package com.interactioncue;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

public class InteractionCueItemOverlay extends WidgetItemOverlay
{
	private final InteractionCuePlugin plugin;
	private final InteractionCueConfig config;

	@Inject
	InteractionCueItemOverlay(InteractionCuePlugin plugin, InteractionCueConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem item)
	{
		InteractionCue cue = plugin.getPendingCue();
		if (!config.pendingMarker()
			|| !cue.isActive()
			|| !plugin.isPendingSlot(item.getWidget(), itemId, item.getQuantity()))
		{
			return;
		}

		Rectangle itemBounds = item.getCanvasBounds();
		int iconSize = config.pendingMarkerIconSize();
		Rectangle markerBounds = getMarkerBounds(
			itemBounds,
			iconSize + config.pendingMarkerPaddingLeft() + config.pendingMarkerPaddingRight(),
			iconSize + config.pendingMarkerPaddingTop() + config.pendingMarkerPaddingBottom()
		);
		Rectangle iconBounds = new Rectangle(
			markerBounds.x + config.pendingMarkerPaddingLeft(),
			markerBounds.y + config.pendingMarkerPaddingTop(),
			iconSize,
			iconSize
		);
		Color color = config.pendingMarkerColor();

		if (config.pendingMarkerBackground())
		{
			graphics.setColor(config.pendingMarkerBackgroundColor());
			fillBackground(graphics, markerBounds, config.pendingMarkerCorner());
		}

		if (config.pendingMarkerIcon())
		{
			BufferedImage image = cue.getImage();
			if (image != null)
			{
				drawImage(graphics, image, iconBounds);
			}
		}

		if (config.pendingMarkerBorder())
		{
			Stroke stroke = graphics.getStroke();
			graphics.setColor(color);
			graphics.setStroke(new BasicStroke((float) config.pendingMarkerBorderWidth()));
			drawBorder(graphics, markerBounds, config.pendingMarkerCorner());
			graphics.setStroke(stroke);
		}
	}

	private Rectangle getMarkerBounds(Rectangle itemBounds, int width, int height)
	{
		InteractionCueMarkerOrigin origin = config.pendingMarkerOrigin();
		int x = itemBounds.x;
		int y = itemBounds.y;
		switch (origin)
		{
			case TOP_CENTER:
				x += (itemBounds.width - width) / 2;
				break;
			case TOP_RIGHT:
				x += itemBounds.width - width;
				break;
			case CENTER_LEFT:
				y += (itemBounds.height - height) / 2;
				break;
			case CENTER:
				x += (itemBounds.width - width) / 2;
				y += (itemBounds.height - height) / 2;
				break;
			case CENTER_RIGHT:
				x += itemBounds.width - width;
				y += (itemBounds.height - height) / 2;
				break;
			case BOTTOM_LEFT:
				y += itemBounds.height - height;
				break;
			case BOTTOM_CENTER:
				x += (itemBounds.width - width) / 2;
				y += itemBounds.height - height;
				break;
			case BOTTOM_RIGHT:
				x += itemBounds.width - width;
				y += itemBounds.height - height;
				break;
			default:
				break;
		}

		return new Rectangle(x + config.pendingMarkerXOffset(), y + config.pendingMarkerYOffset(), width, height);
	}

	private void drawImage(Graphics2D graphics, BufferedImage image, Rectangle bounds)
	{
		double scale = Math.min(bounds.width / (double) image.getWidth(), bounds.height / (double) image.getHeight());
		int width = Math.max(1, (int) Math.round(image.getWidth() * scale));
		int height = Math.max(1, (int) Math.round(image.getHeight() * scale));
		int x = bounds.x + (bounds.width - width) / 2;
		int y = bounds.y + (bounds.height - height) / 2;
		graphics.drawImage(image, x, y, width, height, null);
	}

	private void fillBackground(Graphics2D graphics, Rectangle bounds, int corner)
	{
		if (corner <= 0)
		{
			graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
			return;
		}

		graphics.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, corner * 2, corner * 2);
	}

	private void drawBorder(Graphics2D graphics, Rectangle bounds, int corner)
	{
		if (corner <= 0)
		{
			graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
			return;
		}

		graphics.drawRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, corner * 2, corner * 2);
	}
}

package com.interactioncue;

import java.awt.BasicStroke;
import java.awt.Canvas;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class InteractionCueCursorOverlay extends Overlay
{
	private final Client client;
	private final InteractionCuePlugin plugin;
	private final InteractionCueConfig config;

	@Inject
	InteractionCueCursorOverlay(Client client, InteractionCuePlugin plugin, InteractionCueConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.cursorIndicator() || isMenuInteractionActive())
		{
			return null;
		}

		InteractionCue cue = plugin.getCurrentCue();
		if (!cue.isActive())
		{
			return null;
		}

		Point mouse = client.getMouseCanvasPosition();
		if (!isMouseInsideCanvas(mouse))
		{
			return null;
		}

		int size = config.iconSize();
		FontMetrics metrics = graphics.getFontMetrics();
		List<InteractionCueLabelPart> label = parseLabel(cue);
		if (label.isEmpty())
		{
			return null;
		}

		int contentWidth = getLabelWidth(metrics, label, size);
		int contentHeight = getLabelHeight(metrics, label, size);
		int left = config.backgroundPaddingLeft();
		int top = config.backgroundPaddingTop();
		int right = config.backgroundPaddingRight();
		int bottom = config.backgroundPaddingBottom();
		Rectangle bounds = getTooltipBounds(mouse.getX(), mouse.getY(), contentWidth + left + right, contentHeight + top + bottom);
		int x = bounds.x + left;
		int y = bounds.y + top;
		Color backgroundColor = config.backgroundColor();

		if (config.background() && backgroundColor.getAlpha() > 0)
		{
			graphics.setColor(backgroundColor);
			fillBackground(graphics, bounds, config.backgroundCorner());
		}

		if (config.tooltipBorder() && config.tooltipBorderWidth() > 0 && config.tooltipBorderColor().getAlpha() > 0)
		{
			Stroke stroke = graphics.getStroke();
			graphics.setColor(config.tooltipBorderColor());
			graphics.setStroke(new BasicStroke((float) config.tooltipBorderWidth()));
			drawBorder(graphics, bounds, config.backgroundCorner());
			graphics.setStroke(stroke);
		}

		drawLabel(graphics, label, x, y, contentHeight, size, metrics);

		return null;
	}

	private boolean isMenuInteractionActive()
	{
		return client.isMenuOpen() || client.getMouseCurrentButton() == MouseEvent.BUTTON3;
	}

	private boolean isMouseInsideCanvas(Point mouse)
	{
		if (mouse == null || mouse.getX() < 0 || mouse.getY() < 0 || mouse.getX() >= client.getCanvasWidth() || mouse.getY() >= client.getCanvasHeight())
		{
			return false;
		}

		Canvas canvas = client.getCanvas();
		return canvas == null || canvas.getMousePosition() != null;
	}

	private Rectangle getTooltipBounds(int mouseX, int mouseY, int width, int height)
	{
		InteractionCueTooltipOrigin origin = config.tooltipOrigin();
		if (origin == InteractionCueTooltipOrigin.AUTO)
		{
			origin = InteractionCueTooltipOrigin.CENTER_LEFT;
		}

		Rectangle bounds = getTooltipBoundsForOrigin(origin, mouseX, mouseY, width, height);
		if (bounds.x < 0 || bounds.x + bounds.width > client.getCanvasWidth())
		{
			origin = mirrorHorizontal(origin);
			bounds = getTooltipBoundsForOrigin(origin, mouseX, mouseY, width, height);
		}
		if (bounds.y < 0 || bounds.y + bounds.height > client.getCanvasHeight())
		{
			origin = mirrorVertical(origin);
			bounds = getTooltipBoundsForOrigin(origin, mouseX, mouseY, width, height);
		}
		bounds.x = clamp(bounds.x, 0, Math.max(0, client.getCanvasWidth() - bounds.width));
		bounds.y = clamp(bounds.y, 0, Math.max(0, client.getCanvasHeight() - bounds.height));
		return bounds;
	}

	private InteractionCueTooltipOrigin mirrorHorizontal(InteractionCueTooltipOrigin origin)
	{
		switch (origin)
		{
			case TOP_LEFT:
				return InteractionCueTooltipOrigin.TOP_RIGHT;
			case TOP_RIGHT:
				return InteractionCueTooltipOrigin.TOP_LEFT;
			case CENTER_LEFT:
				return InteractionCueTooltipOrigin.CENTER_RIGHT;
			case CENTER_RIGHT:
				return InteractionCueTooltipOrigin.CENTER_LEFT;
			case BOTTOM_LEFT:
				return InteractionCueTooltipOrigin.BOTTOM_RIGHT;
			case BOTTOM_RIGHT:
				return InteractionCueTooltipOrigin.BOTTOM_LEFT;
			default:
				return origin;
		}
	}

	private InteractionCueTooltipOrigin mirrorVertical(InteractionCueTooltipOrigin origin)
	{
		switch (origin)
		{
			case TOP_LEFT:
				return InteractionCueTooltipOrigin.BOTTOM_LEFT;
			case TOP_CENTER:
				return InteractionCueTooltipOrigin.BOTTOM_CENTER;
			case TOP_RIGHT:
				return InteractionCueTooltipOrigin.BOTTOM_RIGHT;
			case BOTTOM_LEFT:
				return InteractionCueTooltipOrigin.TOP_LEFT;
			case BOTTOM_CENTER:
				return InteractionCueTooltipOrigin.TOP_CENTER;
			case BOTTOM_RIGHT:
				return InteractionCueTooltipOrigin.TOP_RIGHT;
			default:
				return origin;
		}
	}

	private Rectangle getTooltipBoundsForOrigin(InteractionCueTooltipOrigin origin, int mouseX, int mouseY, int width, int height)
	{
		int xOffset = config.xOffset();
		int yOffset = config.yOffset();
		switch (origin)
		{
			case TOP_LEFT:
				return new Rectangle(mouseX + xOffset, mouseY + yOffset, width, height);
			case TOP_CENTER:
				return new Rectangle(mouseX + xOffset - width / 2, mouseY + yOffset, width, height);
			case TOP_RIGHT:
				return new Rectangle(mouseX - xOffset - width, mouseY + yOffset, width, height);
			case CENTER_LEFT:
				return new Rectangle(mouseX + xOffset, mouseY + yOffset - height / 2, width, height);
			case CENTER:
				return new Rectangle(mouseX + xOffset - width / 2, mouseY + yOffset - height / 2, width, height);
			case CENTER_RIGHT:
				return new Rectangle(mouseX - xOffset - width, mouseY + yOffset - height / 2, width, height);
			case BOTTOM_LEFT:
				return new Rectangle(mouseX + xOffset, mouseY - yOffset - height, width, height);
			case BOTTOM_CENTER:
				return new Rectangle(mouseX + xOffset - width / 2, mouseY - yOffset - height, width, height);
			case BOTTOM_RIGHT:
				return new Rectangle(mouseX - xOffset - width, mouseY - yOffset - height, width, height);
			default:
				return new Rectangle(mouseX + xOffset, mouseY + yOffset, width, height);
		}
	}

	private int clamp(int value, int min, int max)
	{
		return Math.max(min, Math.min(max, value));
	}

	private void drawImage(Graphics2D graphics, BufferedImage image, int x, int y, int size)
	{
		double scale = Math.min(size / (double) image.getWidth(), size / (double) image.getHeight());
		int width = Math.max(1, (int) Math.round(image.getWidth() * scale));
		int height = Math.max(1, (int) Math.round(image.getHeight() * scale));
		graphics.drawImage(image, x + (size - width) / 2, y + (size - height) / 2, width, height, null);
	}

	List<InteractionCueLabelPart> parseLabel(InteractionCue cue)
	{
		List<InteractionCueLabelPart> parts = new ArrayList<>();
		parseFormat(config.labelFormat(), cue, parts, new ColorState(Color.WHITE));
		return parts;
	}

	private void parseFormat(String format, InteractionCue cue, List<InteractionCueLabelPart> parts, ColorState state)
	{
		StringBuilder text = new StringBuilder();

		for (int i = 0; i < format.length(); )
		{
			if (format.charAt(i) == '\\' && i + 1 < format.length())
			{
				text.append(format.charAt(i + 1));
				i += 2;
			}
			else if (format.charAt(i) == '{')
			{
				int end = findTokenEnd(format, i);
				if (end < 0)
				{
					text.append(format.charAt(i));
					i++;
				}
				else
				{
					String token = format.substring(i + 1, end);
					if (parseToken(token, cue, parts, text, state))
					{
						i = end + 1;
						continue;
					}

					text.append(format, i, end + 1);
					i = end + 1;
				}
			}
			else
			{
				text.append(format.charAt(i));
				i++;
			}
		}

		addPart(parts, text, state.color);
	}

	private boolean parseToken(String token, InteractionCue cue, List<InteractionCueLabelPart> parts, StringBuilder text, ColorState state)
	{
		List<String> conditional = splitTopLevel(token);
		if (conditional.size() > 1)
		{
			addPart(parts, text, state.color);
			String condition = conditional.get(0).trim();
			boolean inverted = condition.startsWith("!");
			String value = getValue(inverted ? condition.substring(1).trim() : condition, cue);
			boolean matches = !value.isEmpty();
			String branch = matches != inverted ? conditional.get(1) : conditional.size() > 2 ? conditional.get(2) : "";
			parseFormat(branch.replace("@1", value), cue, parts, state);
			return true;
		}

		if ("action".equals(token))
		{
			text.append(cue.getAction());
			return true;
		}

		if ("source".equals(token) || "tool".equals(token))
		{
			text.append(cue.getSource());
			return true;
		}

		if ("target".equals(token))
		{
			text.append(cue.getTarget());
			return true;
		}

		if ("source_icon".equals(token))
		{
			addPart(parts, text, state.color);
			parts.add(new InteractionCueLabelPart(cue.getImage(), cue.getColor(), cue.getSourceShortLabel()));
			return true;
		}

		if ("action_icon".equals(token) || "icon".equals(token))
		{
			addPart(parts, text, state.color);
			parts.add(new InteractionCueLabelPart(cue.getImage(), cue.getColor(), cue.getActionShortLabel()));
			return true;
		}

		if (token.startsWith("#"))
		{
			Color parsed = parseColor(token.substring(1));
			if (parsed != null)
			{
				addPart(parts, text, state.color);
				state.color = parsed;
				return true;
			}
		}

		return false;
	}

	private void addPart(List<InteractionCueLabelPart> parts, StringBuilder text, Color color)
	{
		if (text.length() == 0)
		{
			return;
		}

		parts.add(new InteractionCueLabelPart(text.toString(), color));
		text.setLength(0);
	}

	private void drawLabel(Graphics2D graphics, List<InteractionCueLabelPart> parts, int x, int y, int height, int iconSize, FontMetrics metrics)
	{
		int labelX = x;
		int baseline = y + (height + metrics.getAscent() - metrics.getDescent()) / 2;
		for (InteractionCueLabelPart part : parts)
		{
			if (part.isImage())
			{
				drawIcon(graphics, part, labelX, y + (height - iconSize) / 2, iconSize, metrics);
				labelX += iconSize;
				continue;
			}

			graphics.setColor(part.getColor());
			graphics.drawString(part.getText(), labelX, baseline);
			labelX += metrics.stringWidth(part.getText());
		}
	}

	private void drawIcon(Graphics2D graphics, InteractionCueLabelPart part, int x, int y, int size, FontMetrics metrics)
	{
		BufferedImage image = part.getImage();
		if (image != null)
		{
			drawImage(graphics, image, x, y, size);
			return;
		}

		graphics.setColor(part.getImageColor());
		graphics.fillRoundRect(x, y, size, size, 6, 6);
		graphics.setColor(Color.WHITE);
		String fallback = part.getText();
		graphics.drawString(fallback, x + (size - metrics.stringWidth(fallback)) / 2, y + (size + metrics.getAscent() - metrics.getDescent()) / 2);
	}

	private int getLabelWidth(FontMetrics metrics, List<InteractionCueLabelPart> parts, int iconSize)
	{
		int width = 0;
		for (InteractionCueLabelPart part : parts)
		{
			width += part.isImage() ? iconSize : metrics.stringWidth(part.getText());
		}
		return width;
	}

	private int getLabelHeight(FontMetrics metrics, List<InteractionCueLabelPart> parts, int iconSize)
	{
		int height = 0;
		for (InteractionCueLabelPart part : parts)
		{
			height = Math.max(height, part.isImage() ? iconSize : metrics.getHeight());
		}
		return Math.max(1, height);
	}

	private int findTokenEnd(String value, int start)
	{
		int depth = 0;
		for (int i = start; i < value.length(); i++)
		{
			char ch = value.charAt(i);
			if (ch == '\\' && i + 1 < value.length())
			{
				i++;
			}
			else if (ch == '{')
			{
				depth++;
			}
			else if (ch == '}')
			{
				depth--;
				if (depth == 0)
				{
					return i;
				}
			}
		}

		return -1;
	}

	static List<String> splitTopLevel(String value)
	{
		List<Integer> separators = new ArrayList<>();
		int depth = 0;
		for (int i = 0; i < value.length(); i++)
		{
			char ch = value.charAt(i);
			if (ch == '\\' && i + 1 < value.length())
			{
				i++;
			}
			else if (ch == '{')
			{
				depth++;
			}
			else if (ch == '}')
			{
				depth--;
			}
			else if (ch == ':' && depth == 0)
			{
				separators.add(i);
				if (separators.size() == 2)
				{
					break;
				}
			}
		}

		if (separators.isEmpty())
		{
			return new ArrayList<>();
		}

		List<String> parts = new ArrayList<>();
		int first = separators.get(0);
		parts.add(value.substring(0, first));
		if (separators.size() == 1)
		{
			parts.add(value.substring(first + 1));
			return parts;
		}

		int second = separators.get(1);
		parts.add(value.substring(first + 1, second));
		parts.add(value.substring(second + 1));
		return parts;
	}

	private String getValue(String name, InteractionCue cue)
	{
		switch (name)
		{
			case "action":
				return cue.getAction();
			case "source":
			case "tool":
				return cue.getSource();
			case "target":
				return cue.getTarget();
			default:
				return "";
		}
	}

	private Color parseColor(String value)
	{
		if (value.length() == 3)
		{
			String expanded = "" + value.charAt(0) + value.charAt(0) + value.charAt(1) + value.charAt(1) + value.charAt(2) + value.charAt(2);
			return parseColor(expanded);
		}

		if (value.length() != 6)
		{
			return null;
		}

		try
		{
			return new Color(Integer.parseInt(value, 16));
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}

	private void fillBackground(Graphics2D graphics, Rectangle bounds, int corner)
	{
		if (corner <= 0)
		{
			graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
			return;
		}

		graphics.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, corner * 2, corner * 2);
	}

	private void drawBorder(Graphics2D graphics, Rectangle bounds, int corner)
	{
		if (corner <= 0)
		{
			graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
			return;
		}

		graphics.drawRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, corner * 2, corner * 2);
	}

	private static class ColorState
	{
		private Color color;

		private ColorState(Color color)
		{
			this.color = color;
		}
	}
}

package com.interactioncue;

import java.awt.Color;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

public enum InteractionCueMarkerPreset
{
	CUSTOM("Custom", ruinedHeirSettings()),
	RUINED_HEIR("Ruined Heir's", ruinedHeirSettings()),
