	private int getSpriteId(Widget widget)
	{
		if (widget.getSpriteId() > 0)
		{
			return widget.getSpriteId();
		}

		Widget[] children = widget.getChildren();
		if (children == null)
		{
			return -1;
		}

		for (Widget child : children)
		{
			if (child == null)
			{
				continue;
			}

			int spriteId = getSpriteId(child);
			if (spriteId > 0)
			{
				return spriteId;
			}
		}

		return -1;
	}

