			|| cleaned.startsWith("you can't use ")
			|| cleaned.startsWith("you cannot use ")
			|| cleaned.startsWith("you can't cast ")
			|| cleaned.startsWith("you cannot cast ")
			|| cleaned.startsWith("you don't have ")
